INSERT INTO agent_messages VALUES(21,'64f30a0c-83a9-47ec-83a0-a664114a93eb','{"call_id": "call_ZKXZVaR34LKNEjrAY04jlFBY", "output": "{\"type\":\"text\",\"text\":\"{\\n  \\\"sections\\\": [\\n    {\\n      \\\"section_id\\\": \\\"\\\",\\n      \\\"document_id\\\": \\\"3b6f7de1992992955b87ed2e9673e611\\\",\\n      \\\"heading\\\": \\\"Endnotes\\\",\\n      \\\"text\\\": \\\"[ORG=cpso] [TYPE=advice] [TOPIC=] ^1. See eHealth Ontario for more information on ONE ID.\\\\n\\\\n^2. See OntarioMD (https://www.ontariomd.ca/pages/overview-of-econsult.aspx) or the Ontario Telemedicine Network (https://otn.ca/patients/econsult/) for more information.\\\\n\\\\n^3. See the University of Health Network\u2019s OpenLab work on [*Patient Oriented Discharge Summaries*](http://uhnopenlab.ca/project/pods/), which are now being adopted by hospitals across Ontario.\\\\n\\\\n^4. This is particularly true for physicia\\\",\\n      \\\"chunk_type\\\": \\\"child\\\",\\n      \\\"relevance_score\\\": 0.8,\\n      \\\"metadata\\\": {}\\n    },\\n    {\\n      \\\"section_id\\\": \\\"\\\",\\n      \\\"document_id\\\": \\\"832048ffd9b68a6744c90596331ab329\\\",\\n      \\\"heading\\\": \\\"Using Certified EMRs\\\",\\n      \\\"text\\\": \\\"[ORG=cpso] [TYPE=advice] [TOPIC=] ***How can I determine which EMRs are compliant with privacy legislation and the standards set out in the Regulation?***\\\\n\\\\nIndependently verifying that an unaccredited system meets privacy and security standards is difficult. Physicians may not be experts in information technology or security and thus they may rely on service providers to ensure their EMRs are secure. Organizations like OntarioMD can help physicians navigate their choices and support compliance w\\\",\\n      \\\"chunk_type\\\": \\\"child\\\",\\n      \\\"relevance_score\\\": 0.8,\\n      \\\"metadata\\\": {}\\n    },\\n    {\\n      \\\"section_id\\\": \\\"\\\",\\n      \\\"document_id\\\": \\\"019e4c91d73a65bb16aa24072018befd\\\",\\n      \\\"heading\\\": \\\"Security of Mobile Devices and the Cloud\\\",\\n      \\\"text\\\": \\\"[ORG=cpso] [TYPE=policy] [TOPIC=] 1. When using mobile devices or cloud-based servers to access, store, or back up PHI \u2013 even temporarily \u2013 physicians **must\u00a0**ensure that the PHI on the device or server is protected by encryption.\\\",\\n      \\\"chunk_type\\\": \\\"child\\\",\\n      \\\"relevance_score\\\": 0.8,\\n      \\\"metadata\\\": {}\\n    },\\n    {\\n      \\\"section_id\\\": \\\"\\\",\\n      \\\"document_id\\\": \\\"06bdb229069e2d807723ed61ecefbc30\\\",\\n      \\\"heading\\\": \\\"1. Physicians who will be unavailable during temporary absences from practice **must\u00a0**make specific coverage arrangements with another health-care provider(s) to:\\\\r\\\",\\n      \\\"text\\\": \\\"[ORG=cpso] [TYPE=policy] [TOPIC=privacy,continuity_care] 1. Receive, review, and provide or coordinate immediate care that is required during the temporary absence for all outstanding tests; and\\\",\\n      \\\"chunk_type\\\": \\\"child\\\",\\n      \\\"relevance_score\\\": 0.8,\\n      \\\"metadata\\\": {}\\n    },\\n    {\\n      \\\"section_id\\\": \\\"\\\",\\n      \\\"document_id\\\": \\\"8a3c6a5947d21340c15de9d59344ae8c\\\",\\n      \\\"heading\\\": \\\"3. Physicians **must\u00a0**ensure that voicemail messages are reviewed and responded to in a timely manner. What is timely will depend on, for example, when the message was left and the impact to patient safety that may be caused by a delay in responding.\\\\r\\\",\\n      \\\"text\\\": \\\"[ORG=cpso] [TYPE=policy] [TOPIC=privacy,continuity_care] 1. Physicians who offer electronic means of secure communication^3 **must** similarly ensure that messages are reviewed and responded to in a timely manner.\\\",\\n      \\\"chunk_type\\\": \\\"child\\\",\\n      \\\"relevance_score\\\": 0.8,\\n      \\\"metadata\\\": {}\\n    }\\n  ],\\n  \\\"documents\\\": [\\n    {\\n      \\\"document_id\\\": \\\"3b6f7de1992992955b87ed2e9673e611\\\",\\n      \\\"title\\\": \\\"Advice to the Profession: Continuity of Care\\\",\\n      \\\"source_org\\\": \\\"cpso\\\",\\n      \\\"document_type\\\": \\\"advice\\\",\\n      \\\"effective_date\\\": \\\"\\\",\\n      \\\"topics\\\": [],\\n      \\\"url\\\": \\\"https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care\\\",\\n      \\\"is_superseded\\\": false\\n    },\\n    {\\n      \\\"document_id\\\": \\\"832048ffd9b68a6744c90596331ab329\\\",\\n      \\\"title\\\": \\\"Advice to the Profession: Medical Records Management\\\",\\n      \\\"source_org\\\": \\\"cpso\\\",\\n      \\\"document_type\\\": \\\"advice\\\",\\n      \\\"effective_date\\\": \\\"\\\",\\n      \\\"topics\\\": [],\\n      \\\"url\\\": \\\"https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Medical-Records-Management/Advice-to-the-Profession-Medical-Records-Managemen\\\",\\n      \\\"is_superseded\\\": false\\n    },\\n    {\\n      \\\"document_id\\\": \\\"019e4c91d73a65bb16aa24072018befd\\\",\\n      \\\"title\\\": \\\"Protecting Personal Health Information\\\",\\n      \\\"source_org\\\": \\\"cpso\\\",\\n      \\\"document_type\\\": \\\"policy\\\",\\n      \\\"effective_date\\\": \\\"\\\",\\n      \\\"topics\\\": [],\\n      \\\"url\\\": \\\"https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Protecting-Personal-Health-Information\\\",\\n      \\\"is_superseded\\\": false\\n    },\\n    {\\n      \\\"document_id\\\": \\\"06bdb229069e2d807723ed61ecefbc30\\\",\\n      \\\"title\\\": \\\"Availability and Coverage\\\",\\n      \\\"source_org\\\": \\\"cpso\\\",\\n      \\\"document_type\\\": \\\"policy\\\",\\n      \\\"effective_date\\\": \\\"\\\",\\n      \\\"topics\\\": [\\n        \\\"privacy\\\",\\n        \\\"continuity_care\\\",\\n        \\\"prescribing\\\",\\n        \\\"documentation\\\"\\n      ],\\n      \\\"url\\\": \\\"https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Availab